app.get('/movies/:id', (req, res) => {
  const movie = store.get(req.params.id);        // one model
  res.format({
    html:    () => res.render('movie', { movie }),          // pug/hbs/ejs view
    json:    () => res.json(movie),
    xml:     () => res.type('application/xml').send(toXml(movie)),
    default: () => res.status(406).end(),
  });
});
